const $=s=>document.querySelector(s);
const content=$("#content");
let me=null;
const fullAccess=()=>!!me&&(me.role==="admin"||Number(me.rank_level)>=10);
const staffManager=()=>!!me&&(me.role==="admin"||Number(me.rank_level)>=8);
const canDeleteCases=()=>!!me&&(me.role==="admin"||Number(me.rank_level)>=2);
const pageTitles={dashboard:"Dashboard",cases:"Sager",persons:"Person Register",vehicles:"Køretøjs Database",fleet:"Flådestyring",calls:"Opkaldsliste",warrants:"Efterlysninger",board:"Opslagstavle",fines:"Bødetakster",employees:"Ansatte",ranks:"Rangadministration",applications:"Ansøgninger",logs:"Logs",settings:"Indstillinger"};
let publicSettings={};
const defaultAppearance={font_scale:100,text_color:"#d8d9dd",tablet_color:"#1d1f25"};

async function api(url,opts={}){
  const r=await fetch(url,{headers:{"Content-Type":"application/json",...(opts.headers||{})},...opts});
  const data=await r.json().catch(()=>({}));
  if(!r.ok) throw new Error(data.error||"Anmodningen kunne ikke gennemføres");
  return data;
}
function esc(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function pack(v){return encodeURIComponent(JSON.stringify(v))}
function unpack(v){return JSON.parse(decodeURIComponent(v))}
function money(v){return new Intl.NumberFormat("da-DK").format(Number(v)||0)+" kr."}
function prisonTerm(v={}){const months=Number(v.prison_months)||0,days=Number(v.prison_days)||0;return [months?`${months} mdr`:"",days?`${days} dage`:""].filter(Boolean).join(" + ")||"0 dage"}
function date(v,withTime=false){return v?new Date(v).toLocaleString("da-DK",withTime?{dateStyle:"short",timeStyle:"short"}:{dateStyle:"short"}):"—"}
function toast(message,type="ok"){$("#toast").textContent=message;$("#toast").className=`toast show ${type}`;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$("#toast").className="toast",3200)}
function modal(title,html,onSubmit){
  const el=document.createElement("div");el.className="modal";
  el.innerHTML=`<div class="modalbox"><button class="close" type="button" aria-label="Luk" onclick="closeModal(this)">×</button><h2>${esc(title)}</h2>${html}</div>`;
  document.body.appendChild(el);el.addEventListener("click",e=>{if(e.target===el){destroyCoordinateMap();el.remove()}});
  const form=el.querySelector("form");if(form)form.onsubmit=async e=>{e.preventDefault();const submit=form.querySelector('[type="submit"],button:not([type])');if(submit)submit.disabled=true;try{await onSubmit(new FormData(form));destroyCoordinateMap();el.remove();toast("Ændringer gemt");await route(location.hash.slice(1)||"dashboard")}catch(x){toast(x.message,"error");if(submit)submit.disabled=false}};
}
function closeModal(button){destroyCoordinateMap();button.closest(".modal").remove()}
function destroyCoordinateMap(){if(window.coordinatePickMap){window.coordinatePickMap.remove();window.coordinatePickMap=null;window.coordinatePickMarker=null}}
function toolbar(search,placeholder,action,label,extra="") {return `<div class="toolbar"><form class="searchbar" onsubmit="${search}(event)"><input class="search" id="searchInput" value="${esc(new URLSearchParams(location.search).get("q")||"")}" placeholder="${esc(placeholder)}"><button class="btn" type="submit">Søg</button></form>${extra}<button class="btn primary-btn" onclick="${action}()">＋ ${label}</button></div>`}
function table(headers,rows,empty="Ingen poster at vise"){
  const body=Array.isArray(rows)?rows.join(""):String(rows||"");
  if(!body)return `<div class="empty"><span>⌕</span><strong>${esc(empty)}</strong><small>Prøv at ændre din søgning eller opret en ny post.</small></div>`;
  return `<div class="table-wrap"><table class="table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join("")}</tr></thead><tbody>${body}</tbody></table></div>`;
}
function shell(title,subtitle,body,tools=""){
  const p=location.hash.slice(1)||"dashboard";
  document.querySelectorAll("[data-page]").forEach(b=>b.classList.toggle("active",b.dataset.page===p));
  const pageClass=Object.hasOwn(pageTitles,p)?p:"dashboard";
  content.dataset.page=pageClass;
  content.innerHTML=`<div class="page-head page-head-${pageClass}"><div><div class="eyebrow">POLITI · SAGSSTYRING</div><h1>${title}</h1>${subtitle?`<p class="muted">${subtitle}</p>`:""}</div>${tools}</div>${body}`;
}
function empty(title,description){return `<div class="empty"><span>⌕</span><strong>${esc(title)}</strong><small>${esc(description)}</small></div>`}
function rowsFrom(items,fn){return items.map(fn).join("")}

async function dashboard(){
  const [d,staff]=await Promise.all([api("/api/dashboard"),api("/api/employees")]);
  const newestPost=(d.announcements||[])[0];
  const body=`<section class="stats-grid dashboard-stats">
    ${stat("Total Sager",d.cases,"cases","▣")}${stat("Total Efterlysninger",d.warrants,"warrants","⌕")}${stat("Total Personer",d.persons,"persons","♙")}${stat("Total Køretøjer",d.vehicles,"vehicles","▣")}
  </section><div class="dashboard-live-links"><a href="#fleet">🚔 ${Number(d.fleetAvailable)||0} ledige patruljebiler</a><a href="#calls">☎ ${Number(d.activeCalls)||0} aktive opkald</a></div><section class="dashboard-grid dashboard-reference-grid">
    <div class="panel dashboard-cases"><div class="panel-head"><div><h2>Seneste KR Indlæg</h2></div><button class="link-btn" onclick="location.hash='cases'">Vis alle →</button></div>
      ${table(["SAGSNUMMER","PERSON","DATO","BETJENT","BØDE","FÆNGSEL"],rowsFrom(d.recentCases||[],c=>`<tr><td><span class="mono">${esc(c.case_number)}</span></td><td>${esc(c.person_name||"—")}</td><td>${date(c.created_at,true)}</td><td><span class="person-cell"><span class="avatar avatar-sm">${esc(initials(c.officer_name))}</span>${esc(c.officer_name||"—")}</span></td><td>${money(c.fine_dkk)}</td><td>${prisonTerm(c)}</td></tr>`),"Ingen sager endnu")}</div>
    <div class="panel dashboard-apps"><div class="panel-head"><div><h2>Seneste Ansøgninger</h2></div><button class="link-btn" onclick="location.hash='applications'">Vis alle →</button></div>
      ${(d.pendingApplications||[]).length?`<div class="activity-list">${rowsFrom(d.pendingApplications,a=>`<button class="activity" onclick="location.hash='applications'"><span class="avatar">${esc(initials(a.applicant_name))}</span><span><b>${esc(a.applicant_name)}</b><small>${esc(a.type)} · ${date(a.created_at)}</small></span><span class="btn primary-btn application-review">Åbn</span></button>`)}</div>`:empty("Ingen nye ansøgninger","Indsendte ansøgninger vises her.")}</div>
    <div class="panel dashboard-staff"><div class="panel-head"><div><h2>Ansatte</h2></div><button class="link-btn" onclick="location.hash='employees'">Vis alle →</button></div>
      ${table(["BETJENT","RANG","AKTIV SOM","ON DUTY","DETALJER"],rowsFrom(staff.slice(0,4),e=>`<tr><td><span class="person-cell"><span class="avatar avatar-sm">${esc(initials(e.full_name))}</span>${esc(e.full_name)}</span></td><td>${esc(e.rank||"Betjent")}</td><td>${esc(e.active?"Aktiv":"Offline")}</td><td><span class="status ${e.active?"open":"closed"}">${e.active?"JA":"NEJ"}</span></td><td><button class="btn subtle" onclick="location.hash='employees'">Åbn</button></td></tr>`),"Ingen ansatte")}</div>
    <div class="panel dashboard-quote"><div class="panel-head"><h2>Dagens Besked</h2><button class="link-btn" onclick="location.hash='board'">Vis alle →</button></div>${newestPost?`<div class="dashboard-quote-mark">“</div><blockquote>${esc(newestPost.body)}</blockquote><div class="dashboard-quote-footer"><span class="avatar avatar-sm">${esc(initials(newestPost.author_name||"POLITI"))}</span><span>${esc(newestPost.author_name||"POLITI")}<small>${esc(newestPost.rank||"Rigspolitichef")}</small></span></div>`:`<div class="dashboard-quote-mark">“</div><blockquote>Hej med jer</blockquote><div class="dashboard-quote-footer"><span class="avatar avatar-sm">P</span><span>Rigspolitiet<small>POLITI</small></span></div>`}</div>
  </section>`;
  shell("Dashboard","Overblik over politiets registre og dagens aktivitet.",body);
}
function initials(name){return String(name||"?").trim().split(/\s+/).slice(0,2).map(x=>x[0]).join("").toUpperCase()}
function stat(label,value,page,icon){return `<button class="stat-card" onclick="location.hash='${page}'"><span class="stat-icon">${icon}</span><span class="stat-label">${label}</span><strong>${Number(value)||0}</strong><span class="stat-foot">Gå til register <b>→</b></span></button>`}

async function persons(){
  const qv=new URLSearchParams(location.search).get("q")||"";const rows=await api("/api/persons?search="+encodeURIComponent(qv));
  shell("Person Register","Søg i personregistret, og få adgang til sager, køretøjer og efterlysninger.",`${toolbar("searchPersons","Søg på navn eller telefonnummer","newPerson","Opret person")}${table(["PERSON","FØDSELSDATO","TELEFON","ADRESSE",""],rowsFrom(rows,p=>`<tr><td><button class="person-cell" onclick="person(${p.id})"><span class="avatar">${esc(initials(p.name))}</span><span><b>${esc(p.name)}</b><small class="cell-sub">${p.source&&p.source!=="manual"?`${esc(p.source)} · RP-karakter`:"Manuel registrering"}</small></span></button></td><td>${date(p.birth_date)}</td><td>${esc(p.phone||"—")}</td><td>${esc(p.address||"—")}</td><td class="right"><button class="btn subtle" onclick="person(${p.id})">Åbn person</button></td></tr>`),"Personen blev ikke fundet")}`);
}
function searchPersons(e){e.preventDefault();location.search="?q="+encodeURIComponent($("#searchInput").value.trim())}
function personForm(p={}){return `<form class="form"><div class="form-grid"><label class="wide">Fulde navn<input name="name" value="${esc(p.name)}" required maxlength="160"></label><label>Adresse<input name="address" value="${esc(p.address)}"></label><label>Telefon<input name="phone" value="${esc(p.phone)}"></label><label>Fødselsdato<input type="date" name="birth_date" value="${esc(String(p.birth_date||"").slice(0,10))}"></label><label>Køn<input name="gender" value="${esc(p.gender)}"></label><label class="wide">Noter<textarea name="notes">${esc(p.notes)}</textarea></label></div><button class="btn primary-btn" type="submit">Gem person</button></form>`}
function newPerson(){modal("Opret person",personForm(),async f=>{await api("/api/persons",{method:"POST",body:JSON.stringify(Object.fromEntries(f))})})}
function editPerson(p){modal("Rediger person",personForm(p),async f=>{await api(`/api/persons/${p.id}`,{method:"PATCH",body:JSON.stringify(Object.fromEntries(f))})})}
function editPersonData(encoded){editPerson(unpack(encoded))}
async function person(id){
  const d=await api(`/api/persons/${id}`),p=d.person;
  window.currentPersonCases=d.cases;const evidence=d.seizedItems||[];const evidencePanel=`<div class="panel span-2"><div class="panel-head"><h2>Beslaglagte beviser <span class="count">${evidence.length}</span></h2>${Number(me.rank_level)>=2||fullAccess()?`<button class="btn primary-btn" onclick="newEvidence(${p.id})">＋ Beslaglæg bevis</button>`:""}</div>${evidence.length?table(["GENSTAND","BESKRIVELSE","SAG","BESLAGLAGT AF","DATO"],rowsFrom(evidence,x=>`<tr><td><b>${esc(x.item_name)}</b></td><td>${esc(x.description||"—")}</td><td>${esc(x.case_number||"—")}</td><td>${esc(x.officer_name||"—")}</td><td>${date(x.created_at)}</td></tr>`)):empty("Ingen beslaglagte beviser","Beslaglagte genstande knyttes til personen her.")}</div>`;
  const body=`<div class="detail-top panel"><div class="avatar avatar-xl">${esc(initials(p.name))}</div><div class="detail-main"><div class="eyebrow">PERSON-ID ${p.id}</div><h2>${esc(p.name)}</h2><div class="detail-meta"><span>⌖ ${esc(p.address||"Adresse ikke registreret")}</span><span>☎ ${esc(p.phone||"Telefon ikke registreret")}</span><span>Født ${date(p.birth_date)}</span></div></div><button class="btn" onclick="editPersonData('${pack(p)}')">Rediger person</button><button class="btn primary-btn" onclick="newCase(${p.id})">＋ Opret sag</button></div>
  <div class="dashboard-grid detail-grid"><div class="panel span-2"><div class="panel-head"><h2>Tidligere sager <span class="count">${d.cases.length}</span></h2><button class="link-btn" onclick="newCase(${p.id})">＋ Ny sag</button></div>${table(["SAGSNR.","SAG / TAKSTER","BØDE","KLIP","FÆNGSEL","DATO",""],rowsFrom(d.cases,c=>`<tr><td class="mono">${esc(c.case_number)}</td><td>${esc(c.title)}${c.penalties?.length?`<small class="cell-sub">${esc(c.penalties.map(p=>`${p.code||p.title} × ${p.quantity}`).join(" · "))}</small>`:""}</td><td>${money(c.fine_dkk)}</td><td>${Number(c.license_points)||0}</td><td>${prisonTerm(c)}</td><td>${date(c.created_at)}</td><td class="right">${canDeleteCases()?`<button class="icon-btn danger-text" title="Slet sag" aria-label="Slet sag ${esc(c.case_number)}" onclick="deletePersonCase(${p.id},${c.id},'${esc(c.case_number)}')">×</button>`:"—"}</td></tr>`))}</div>
  ${evidencePanel}<div class="panel"><div class="panel-head"><h2>Personoplysninger</h2></div><p class="detail-note">${esc(p.notes||"Ingen noter er registreret.")}</p><div class="facts"><span>Køn</span><b>${esc(p.gender||"—")}</b><span>Oprettet</span><b>${date(p.created_at)}</b></div></div>
  <div class="panel"><div class="panel-head"><h2>Køretøjer <span class="count">${d.vehicles.length}</span></h2></div>${d.vehicles.length?table(["PLADE","KØRETØJ","STATUS"],rowsFrom(d.vehicles,v=>`<tr><td class="mono">${esc(v.plate)}</td><td>${esc([v.make,v.model].filter(Boolean).join(" ")||"—")}</td><td>${esc(v.status)}</td></tr>`)):empty("Ingen køretøjer","Der er ikke knyttet køretøjer til personen.")}</div>
  <div class="panel"><div class="panel-head"><h2>Efterlysninger <span class="count">${d.warrants.length}</span></h2></div>${d.warrants.length?table(["TITEL","STATUS"],rowsFrom(d.warrants,w=>`<tr><td>${esc(w.title)}</td><td><span class="status ${w.active?"open":"closed"}">${w.active?"Aktiv":"Lukket"}</span></td></tr>`)):empty("Ingen efterlysninger","Personen har ingen efterlysninger.")}</div></div>`;
  shell("Person Register",p.name,body,`<button class="btn subtle" onclick="location.hash='persons'">← Tilbage til registret</button>`);
}
function newEvidence(personId){const options=(window.currentPersonCases||[]).map(c=>`<option value="${c.id}">${esc(c.case_number)} · ${esc(c.title)}</option>`).join("");modal("Beslaglæg bevis",`<form class="form"><label>Genstand<input name="item_name" required maxlength="180" placeholder="F.eks. mobiltelefon"></label><label>Tilknyt sag<select name="case_id"><option value="">Ingen sag valgt</option>${options}</select></label><label>Beskrivelse<textarea name="description"></textarea></label><button class="btn primary-btn" type="submit">Registrer beslag</button></form>`,async f=>{await api(`/api/persons/${personId}/evidence`,{method:"POST",body:JSON.stringify(Object.fromEntries(f))})})}
async function deletePersonCase(personId,caseId,caseNumber){if(!confirm(`Vil du slette sag ${caseNumber} permanent?`))return;try{await api(`/api/persons/${personId}/cases/${caseId}`,{method:"DELETE"});toast(`Sag ${caseNumber} er slettet`);await person(personId)}catch(e){toast(e.message,"error")}}
async function newCase(personId){
  const fines=await api("/api/fines");
  window.casePenaltyCatalog=fines;window.casePenaltyCart=[];window.caseTitleEdited=false;
  const options=caseFineOptions();
  modal("Opret sigtelse / sag",`<form class="form"><label>Søg i lov, paragraf eller sigtelse<input id="caseFineSearch" placeholder="F.eks. §2:1, Våben eller Manddrab" oninput="filterCaseFines(this.value)"></label><div class="penalty-add-row"><label>Vælg lovparagraf eller straf<select id="caseFine"><option value="">Vælg en lov eller takst</option>${options}</select></label><button class="btn primary-btn" type="button" onclick="addCasePenalty()">＋ Tilføj</button></div><div id="casePenaltyList" class="penalty-list"><div class="penalty-empty">Vælg og tilføj en eller flere paragraffer. Gentag for at lægge flere til.</div></div><div class="penalty-totals"><div><span>Samlet bøde</span><strong id="caseTotalFine">0 kr.</strong></div><div><span>Samlet klip</span><strong id="caseTotalPoints">0</strong></div><div><span>Samlet fængsel</span><strong id="caseTotalPrison">0 dage</strong></div></div><input type="hidden" name="penalties" id="casePenalties" value="[]"><input type="hidden" name="fine_dkk" id="casePrice" value="0"><input type="hidden" name="license_points" id="casePoints" value="0"><input type="hidden" name="prison_days" id="casePrison" value="0"><input type="hidden" name="prison_months" id="casePrisonMonths" value="0"><label>Sagstitel<input id="caseTitle" name="title" required maxlength="180" placeholder="Udfyldes automatisk ud fra valgte paragraffer"></label><label>Beskrivelse<textarea name="description"></textarea></label><button class="btn primary-btn" type="submit">Opret sag</button></form>`,async f=>{const payload=Object.fromEntries(f);payload.penalties=JSON.parse(payload.penalties||"[]");await api(`/api/persons/${personId}/cases`,{method:"POST",body:JSON.stringify(payload)})});
  document.querySelector(".modal #caseTitle")?.addEventListener("input",()=>window.caseTitleEdited=true);
}
function caseFineOptions(search=""){const q=String(search).trim().toLocaleLowerCase("da-DK");return (window.casePenaltyCatalog||[]).filter(f=>!q||[f.category,f.code,f.title,f.description].some(v=>String(v||"").toLocaleLowerCase("da-DK").includes(q))).map(f=>`<option value="${f.id}">${esc(f.category)} · ${esc(f.code||"")} ${esc(f.title)} · ${money(f.price_dkk)} · ${Number(f.points)||0} klip · ${prisonTerm(f)}</option>`).join("")}
function filterCaseFines(search){const select=$("#caseFine");if(!select)return;const selected=select.value;select.innerHTML=`<option value="">Vælg en lov eller takst</option>${caseFineOptions(search)}`;if([...select.options].some(o=>o.value===selected))select.value=selected}
function addCasePenalty(){const id=Number($("#caseFine")?.value);if(!id)return toast("Vælg en bøde eller straf først","error");adjustCasePenalty(id,1)}
function adjustCasePenalty(id,change){const fine=window.casePenaltyCatalog?.find(row=>Number(row.id)===Number(id));if(!fine)return;const found=window.casePenaltyCart.find(row=>row.fine_id===Number(id));if(found)found.quantity+=change;else if(change>0)window.casePenaltyCart.push({fine_id:Number(id),quantity:change});window.casePenaltyCart=window.casePenaltyCart.filter(row=>row.quantity>0);renderCasePenalties()}
function renderCasePenalties(){
  const cart=window.casePenaltyCart||[],catalog=window.casePenaltyCatalog||[];
  const list=$("#casePenaltyList"),fineTotal=cart.reduce((n,row)=>{const f=catalog.find(x=>Number(x.id)===row.fine_id);return n+(Number(f?.price_dkk)||0)*row.quantity},0),pointsTotal=cart.reduce((n,row)=>{const f=catalog.find(x=>Number(x.id)===row.fine_id);return n+(Number(f?.points)||0)*row.quantity},0),prisonDays=cart.reduce((n,row)=>{const f=catalog.find(x=>Number(x.id)===row.fine_id);return n+(Number(f?.prison_days)||0)*row.quantity},0),prisonMonths=cart.reduce((n,row)=>{const f=catalog.find(x=>Number(x.id)===row.fine_id);return n+(Number(f?.prison_months)||0)*row.quantity},0);
  if(list)list.innerHTML=cart.length?cart.map(row=>{const f=catalog.find(x=>Number(x.id)===row.fine_id);return `<div class="penalty-row"><div><b>${esc(f?.code?`${f.code} · `:"")}${esc(f?.title||"Ukendt takst")}</b><small>${money((Number(f?.price_dkk)||0)*row.quantity)} · ${(Number(f?.points)||0)*row.quantity} klip · ${prisonTerm({prison_months:(Number(f?.prison_months)||0)*row.quantity,prison_days:(Number(f?.prison_days)||0)*row.quantity})}${f?.description?`<br>${esc(f.description)}`:""}</small></div><div class="penalty-stepper"><button type="button" aria-label="Fjern én" onclick="adjustCasePenalty(${row.fine_id},-1)">−</button><strong>${row.quantity}</strong><button type="button" aria-label="Tilføj én" onclick="adjustCasePenalty(${row.fine_id},1)">＋</button></div></div>`}).join(""):"<div class=\"penalty-empty\">Vælg og tilføj en eller flere paragraffer. Gentag for at lægge flere til.</div>";
  $("#caseTotalFine").textContent=money(fineTotal);$("#caseTotalPoints").textContent=String(pointsTotal);$("#caseTotalPrison").textContent=prisonTerm({prison_months:prisonMonths,prison_days:prisonDays});
  $("#casePrice").value=String(fineTotal);$("#casePoints").value=String(pointsTotal);$("#casePrison").value=String(prisonDays);$("#casePrisonMonths").value=String(prisonMonths);$("#casePenalties").value=JSON.stringify(cart);
  const title=$("#caseTitle");if(title&&!window.caseTitleEdited)title.value=cart.map(row=>{const f=catalog.find(x=>Number(x.id)===row.fine_id);return f?`${f.title}${row.quantity>1?` × ${row.quantity}`:""}`:""}).filter(Boolean).join(" + ");
}

async function vehicles(){const qv=new URLSearchParams(location.search).get("q")||"";const rows=await api("/api/vehicles?search="+encodeURIComponent(qv));
  window.vehicleRows=rows;
  shell("Køretøjs Database","Søg efter nummerplade og administrer køretøjer knyttet til personer.",`${toolbar("searchVehicles","Søg nummerplade, mærke eller model","newVehicle","Registrer køretøj")}${table(["NUMMERPLADE","EJER","KØRETØJ","KATEGORI","STATUS",""],rowsFrom(rows,v=>`<tr><td><span class="plate">${esc(v.plate)}</span></td><td>${esc(v.owner_name||"Ingen registreret ejer")}</td><td>${esc([v.make,v.model].filter(Boolean).join(" ")||"—")}</td><td>${esc(v.category||"—")}</td><td><span class="status ${v.status==="Normal"?"open":"waiting"}">${esc(v.status)}</span></td><td class="right"><button class="btn subtle" onclick="editVehicleById(${v.id})">Rediger</button></td></tr>`),"Køretøjet blev ikke fundet")}`);
}
function searchVehicles(e){e.preventDefault();location.search="?q="+encodeURIComponent($("#searchInput").value.trim())}
async function vehicleForm(v={}){const people=await api("/api/persons");const statusOptions=["Normal","Efterlyst",...(fullAccess()||Number(me.rank_level)>=2||v.status==="Beslaglagt"?["Beslaglagt"]:[]),"Stjålet","Afmeldt"];const opts=people.map(p=>`<option value="${p.id}" ${String(v.owner_id)===String(p.id)?"selected":""}>${esc(p.name)}</option>`).join("");return `<form class="form"><div class="form-grid"><label>Nummerplade<input name="plate" value="${esc(v.plate)}" required></label><label>Ejer<select name="owner_id"><option value="">Ingen ejer</option>${opts}</select></label><label>Mærke<input name="make" value="${esc(v.make)}"></label><label>Model<input name="model" value="${esc(v.model)}"></label><label>Kategori<input name="category" value="${esc(v.category)}"></label><label>Farve<input name="color" value="${esc(v.color)}"></label><label>Status<select name="status">${statusOptions.map(x=>`<option ${v.status===x?"selected":""}>${x}</option>`).join("")}</select></label><label class="wide">Noter<textarea name="notes">${esc(v.notes)}</textarea></label></div><button class="btn primary-btn" type="submit">Gem køretøj</button></form>`}
async function newVehicle(){modal("Registrer køretøj",await vehicleForm(),async f=>{await api("/api/vehicles",{method:"POST",body:JSON.stringify(Object.fromEntries(f))})})}
async function editVehicle(v){modal("Rediger køretøj",await vehicleForm(v),async f=>{await api(`/api/vehicles/${v.id}`,{method:"PATCH",body:JSON.stringify(Object.fromEntries(f))})})}
async function editVehicleById(id){const v=window.vehicleRows.find(x=>x.id===id);if(v)await editVehicle(v)}

const fleetStatusOptions=["Ledig","På vagt","På patrulje","På værksted"];
async function fleet(){const term=new URLSearchParams(location.search).get("q")||"";const rows=await api("/api/fleet?search="+encodeURIComponent(term));window.fleetRows=rows;const admin=fullAccess();
  const available=rows.filter(v=>v.status==="Ledig").length,onDuty=rows.filter(v=>["På vagt","På patrulje"].includes(v.status)).length;
  shell("Flådestyring","Hold styr på patruljebiler, kaldesignaler, medarbejdere og køretøjsstatus.",`<div class="stats-grid fleet-stats"><div class="panel fleet-stat"><span class="stat-icon">🚔</span><span class="stat-label">Køretøjer</span><strong>${rows.length}</strong></div><div class="panel fleet-stat"><span class="stat-icon">✓</span><span class="stat-label">Ledige</span><strong>${available}</strong></div><div class="panel fleet-stat"><span class="stat-icon">◉</span><span class="stat-label">På vagt</span><strong>${onDuty}</strong></div><div class="panel fleet-stat"><span class="stat-icon">⌕</span><span class="stat-label">På værksted</span><strong>${rows.filter(v=>v.status==="På værksted").length}</strong></div></div><div class="toolbar"><form class="searchbar" onsubmit="searchFleet(event)"><input class="search" id="fleetSearch" value="${esc(term)}" placeholder="Søg kaldesignal, nummerplade eller model"><button class="btn">Søg</button></form>${admin?`<button class="btn primary-btn" onclick="newFleetVehicle()">＋ Tilføj patruljekøretøj</button>`:""}</div><section class="panel"><div class="panel-head"><div><h2>Politiets køretøjer</h2><p class="muted">Vælg din status for at overtage et køretøj.</p></div></div>${table(["KALDESIGNAL","NUMMERPLADE","MODEL","STATUS","TILDELT","SENESTE POSITION",...(admin?["HANDLING"]:[])],rowsFrom(rows,v=>`<tr><td><b class="mono">${esc(v.call_sign)}</b></td><td><span class="plate">${esc(v.plate)}</span></td><td>${esc(v.model)}${v.notes?`<small class="cell-sub">${esc(v.notes)}</small>`:""}</td><td><select class="fleet-status-select" aria-label="Status ${esc(v.call_sign)}" onchange="setFleetStatus(${v.id},this.value)">${fleetStatusOptions.map(x=>`<option ${v.status===x?"selected":""}>${x}</option>`).join("")}</select></td><td>${esc(v.assigned_name||"—")}${v.assigned_badge?`<small class="cell-sub">${esc(v.assigned_badge)}</small>`:""}</td><td>${v.location_x==null?"—":`${Number(v.location_x).toFixed(0)}, ${Number(v.location_y).toFixed(0)}`}<small class="cell-sub">${date(v.updated_at,true)}</small></td>${admin?`<td class="right"><button class="btn subtle" onclick="editFleetVehicleById(${v.id})">Rediger</button><button class="icon-btn danger-text" title="Slet køretøj" onclick="deleteFleetVehicle(${v.id})">×</button></td>`:""}</tr>`),"Flåden er tom")}</section>`);
}
function searchFleet(e){e.preventDefault();location.search="?q="+encodeURIComponent($("#fleetSearch").value.trim())}
async function fleetForm(v={}){const people=(await api("/api/employees")).filter(u=>u.active);return `<form class="form"><div class="form-grid"><label>Kaldesignal<input name="call_sign" value="${esc(v.call_sign)}" placeholder="A-01" required maxlength="40"></label><label>Nummerplade<input name="plate" value="${esc(v.plate)}" required maxlength="30"></label><label class="wide">Model<input name="model" value="${esc(v.model)}" placeholder="Patruljevogn" required maxlength="120"></label><label>Status<select name="status">${fleetStatusOptions.map(x=>`<option ${v.status===x?"selected":""}>${x}</option>`).join("")}</select></label><label>Tildelt medarbejder<select name="assigned_to"><option value="">Ingen</option>${people.map(p=>`<option value="${p.id}" ${String(v.assigned_to)===String(p.id)?"selected":""}>${esc(p.full_name)} · ${esc(p.badge_number||p.rank)}</option>`).join("")}</select></label><label class="wide">Noter<textarea name="notes">${esc(v.notes)}</textarea></label></div><button class="btn primary-btn" type="submit">Gem køretøj</button></form>`}
async function newFleetVehicle(){modal("Tilføj patruljekøretøj",await fleetForm(),async f=>api("/api/fleet",{method:"POST",body:JSON.stringify(Object.fromEntries(f))}))}
async function editFleetVehicleById(id){const v=window.fleetRows.find(x=>x.id===id);if(v)modal("Rediger patruljekøretøj",await fleetForm(v),async f=>api(`/api/fleet/${id}`,{method:"PATCH",body:JSON.stringify(Object.fromEntries(f))}))}
async function setFleetStatus(id,status){try{await api(`/api/fleet/${id}/status`,{method:"PATCH",body:JSON.stringify({status})});toast("Flådestatus opdateret");await fleet()}catch(e){toast(e.message,"error");await fleet()}}
async function deleteFleetVehicle(id){if(!confirm("Vil du fjerne køretøjet fra politiets flåde?"))return;await api(`/api/fleet/${id}`,{method:"DELETE"});toast("Køretøjet er fjernet fra flåden");await fleet()}

async function warrants(){const rows=await api("/api/warrants");
  shell("Efterlysninger","Aktive efterlysninger samlet ét sted. Luk en efterlysning, når sagen er afsluttet.",`<div class="toolbar"><div class="filter-tabs"><button class="selected" onclick="filterWarrants('all',this)">Alle <span>${rows.length}</span></button><button onclick="filterWarrants('active',this)">Aktive <span>${rows.filter(x=>x.active).length}</span></button><button onclick="filterWarrants('closed',this)">Lukkede <span>${rows.filter(x=>!x.active).length}</span></button></div><button class="btn primary-btn" onclick="newWarrant()">＋ Opret efterlysning</button></div><div id="warrantTable">${warrantTable(rows)}</div>`);
  window.warrantRows=rows;
}
function warrantTable(rows){return table(["TYPE","PERSON / KØRETØJ","EFTERLYSNING","OPRETTET","STATUS",""],rows.map(w=>`<tr><td><span class="type-icon">${w.type==="Køretøj"?"▣":"♙"}</span>${esc(w.type)}</td><td>${esc(w.person_name||w.plate||"—")}${w.person_name&&w.plate?`<small class="cell-sub">${esc(w.plate)}</small>`:""}</td><td><b>${esc(w.title)}</b><small class="cell-sub">${esc(w.description||"")}</small></td><td>${date(w.created_at)}</td><td><span class="status ${w.active?"danger-status":"closed"}">${w.active?"Aktiv":"Lukket"}</span></td><td class="right">${w.active?`<button class="btn subtle" onclick="toggleWarrant(${w.id},false)">Luk</button>`:`<button class="btn subtle" onclick="toggleWarrant(${w.id},true)">Genåbn</button>`}</td></tr>`),"Ingen efterlysninger")}
function filterWarrants(which,button){document.querySelectorAll(".filter-tabs button").forEach(x=>x.classList.remove("selected"));button.classList.add("selected");const rows=window.warrantRows.filter(x=>which==="all"||(which==="active"&&x.active)||(which==="closed"&&!x.active));$("#warrantTable").innerHTML=warrantTable(rows)}
async function newWarrant(){const [people,vehicles]=await Promise.all([api("/api/persons"),api("/api/vehicles")]);modal("Opret efterlysning",`<form class="form"><label>Efterlysningstype<select name="type"><option>Person</option><option>Køretøj</option></select></label><div class="form-grid"><label>Person<select name="person_id"><option value="">Vælg person</option>${people.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join("")}</select></label><label>Køretøj<select name="vehicle_id"><option value="">Vælg køretøj</option>${vehicles.map(v=>`<option value="${v.id}">${esc(v.plate)} · ${esc(v.make||"")} ${esc(v.model||"")}</option>`).join("")}</select></label></div><label>Titel<input name="title" required></label><label>Beskrivelse<textarea name="description"></textarea></label><button class="btn primary-btn" type="submit">Opret efterlysning</button></form>`,async f=>{const o=Object.fromEntries(f);if(!o.person_id)o.person_id=null;if(!o.vehicle_id)o.vehicle_id=null;if(!o.person_id&&!o.vehicle_id)throw new Error("Vælg en person eller et køretøj");await api("/api/warrants",{method:"POST",body:JSON.stringify(o)})})}
async function toggleWarrant(id,active){await api(`/api/warrants/${id}`,{method:"PATCH",body:JSON.stringify({active})});toast(active?"Efterlysning genåbnet":"Efterlysning lukket");await warrants()}

async function calls(){if(window.dispatchMap){window.dispatchMap.remove();window.dispatchMap=null}const filter=window.callFilter||"open";const rows=await api(`/api/calls?status=${filter}`);window.callRows=rows;
  const all=await api("/api/calls?status=open");
  shell("Opkaldsliste","Modtag, overtag og afslut opkald. Vælg et punkt på GTA V-kortet for at se stedet.",`<div class="toolbar"><div class="filter-tabs"><button class="${filter==="open"?"selected":""}" onclick="filterCalls('open')">Aktive <span>${all.length}</span></button><button class="${filter==="closed"?"selected":""}" onclick="filterCalls('closed')">Afsluttede</button><button class="${filter==="all"?"selected":""}" onclick="filterCalls('all')">Alle</button></div><div class="call-toolbar-actions"><button class="btn subtle" onclick="calls()">↻ Opdater</button><button class="btn primary-btn" onclick="newCall()">＋ Nyt opkald</button></div></div><div class="calls-layout"><section class="panel calls-panel"><div class="panel-head"><div><h2>${filter==="closed"?"Afsluttede opkald":"Aktuelle opkald"}</h2><p class="muted">${rows.length} opkald i visningen</p></div><span class="tag tag-purple">Dispatch</span></div><div class="call-list" id="callList">${rows.length?rows.map(callCard).join(""):empty("Ingen opkald","Nye opkald fra FiveM eller tablet vises her.")}</div></section><aside class="panel call-map-panel"><div class="panel-head"><div><h2>GTA V-kort og koordinater</h2><p class="muted">Kortet viser opkaldene på Los Santos-kortet.</p></div></div><div class="call-map-wrap"><div id="dispatchMap" class="dispatch-map" role="application" aria-label="Interaktivt GTA V-kort"></div></div><div class="map-legend"><span><i class="map-dot pending-dot"></i>Afventer</span><span><i class="map-dot accepted-dot"></i>Overtaget</span></div>${rows.length?`<div class="selected-call" id="selectedCall"><b>Vælg et opkald</b><small>Opkaldets koordinater vises her.</small></div>`:empty("Kortet er tomt","Opkald med koordinater vises som markører.")}</aside></div>`);
  mountCallMap(rows,false);
}
function callCard(c){const owner=c.claimed_name?`${c.claimed_name}${c.claimed_rank?` · ${c.claimed_rank}`:""}`:"Ikke overtaget";const canRelease=c.status==="pending"||fullAccess()||Number(c.claimed_by)===Number(me.id);const phone=String(c.caller_phone||"").replace(/[^\d+]/g,"");return `<article class="call-card" id="call-${c.id}" onclick="focusCall(${c.id})"><div class="call-card-top"><span class="status ${c.status==="pending"?"waiting":c.status==="accepted"?"open":"closed"}">${c.status==="pending"?"Afventer":c.status==="accepted"?"Overtaget":"Afsluttet"}</span><time>${date(c.created_at,true)}</time></div><div class="call-card-heading"><div><span class="eyebrow">${esc(c.category)} · OPKALD #${esc(c.id)}</span><h3>${esc(c.caller_name)}</h3></div><span class="call-coordinates">${Number(c.coord_x).toFixed(0)}, ${Number(c.coord_y).toFixed(0)}</span></div><p class="call-message">${esc(c.message)}</p><div class="call-card-meta"><span>☎ ${esc(c.caller_phone||"Intet telefonnummer")}</span><span>Enhed: ${esc(owner)}</span></div><div class="call-actions">${c.status==="pending"?`<button class="btn primary-btn" onclick="event.stopPropagation();changeCallStatus(${c.id},'accept')">Tag opkald</button>`:""}${c.status==="accepted"&&canRelease?`<button class="btn subtle" onclick="event.stopPropagation();changeCallStatus(${c.id},'release')">Frigiv</button>`:""}${c.status!=="closed"&&canRelease?`<button class="btn subtle" onclick="event.stopPropagation();changeCallStatus(${c.id},'close')">Afslut</button>`:""}<button class="btn subtle" onclick="event.stopPropagation();setCallGPS(${c.id})">Sæt GPS</button>${phone?`<a class="btn subtle" href="tel:${phone}" onclick="event.stopPropagation()">Ring op</a>`:""}</div></article>`}
const gtaMapBounds={tileMin:-9655.77,tileMax:12343.94,tileRange:20357.85,pixelSize:32768,zoom:7};
function gtaToMapPoint(x,y){const b=gtaMapBounds;return L.CRS.Simple.unproject(L.point(((Number(x)-b.tileMin)/b.tileRange)*b.pixelSize,((b.tileMax-Number(y))/b.tileRange)*b.pixelSize),b.zoom)}
function mapPointToGta(latlng,map){const b=gtaMapBounds,p=map.project(latlng,b.zoom);return {x:Math.round((p.x/b.pixelSize*b.tileRange+b.tileMin)*100)/100,y:Math.round((b.tileMax-p.y/b.pixelSize*b.tileRange)*100)/100}}
function mountCallMap(rows=[],picker=false){const el=document.getElementById(picker?"coordinatePicker":"dispatchMap");if(!el)return;if(!window.L){el.innerHTML='<div class="empty"><strong>Kortet kunne ikke indlæses</strong><small>Kontrollér internetforbindelsen, og genindlæs siden.</small></div>';return}const map=L.map(el,{crs:L.CRS.Simple,minZoom:0,maxZoom:7,zoomControl:true,attributionControl:true,zoomSnap:.25,zoomDelta:.5,preferCanvas:true});L.tileLayer("https://s.rsg.sc/sc/images/games/GTAV/map/game/{z}/{x}/{y}.jpg",{minZoom:0,maxZoom:7,noWrap:true,attribution:'<a href="https://www.rockstargames.com/gta-v" target="_blank" rel="noopener">Kortdata © Rockstar Games</a>'}).addTo(map);map.setView(gtaToMapPoint(0,0),picker?3:2);if(picker){window.coordinatePickMap=map;map.on("click",e=>chooseCallCoordinates(e,map));const x=Number($("#callX")?.value||0),y=Number($("#callY")?.value||0);window.coordinatePickMarker=L.circleMarker(gtaToMapPoint(x,y),{radius:8,color:"#fff",weight:2,fillColor:"#7777ff",fillOpacity:1}).addTo(map)}else{window.dispatchMap=map;const markers=[];rows.forEach((c,i)=>{const icon=L.divIcon({className:"call-map-icon",html:`<span id="map-call-${Number(c.id)}" class="call-map-marker ${c.status==="accepted"?"accepted":"pending"}"><b>${i+1}</b></span>`,iconSize:[30,36],iconAnchor:[15,32]});const marker=L.marker(gtaToMapPoint(c.coord_x,c.coord_y),{icon,title:`Opkald #${c.id} · ${c.caller_name}`}).addTo(map);marker.on("click",()=>focusCall(c.id));markers.push(marker)});if(markers.length){const group=L.featureGroup(markers);if(markers.length===1)map.setView(markers[0].getLatLng(),5);else map.fitBounds(group.getBounds().pad(.18),{maxZoom:6})}}setTimeout(()=>map.invalidateSize(),80)}
function filterCalls(filter){window.callFilter=filter;calls()}
function focusCall(id){const c=(window.callRows||[]).find(x=>Number(x.id)===Number(id));if(!c)return;document.querySelectorAll(".call-card").forEach(x=>x.classList.toggle("selected",x.id===`call-${id}`));document.querySelectorAll(".call-map-marker").forEach(x=>x.classList.toggle("selected",x.id===`map-call-${id}`));const box=$("#selectedCall");if(box)box.innerHTML=`<b>${esc(c.category)} · ${esc(c.caller_name)}</b><small>X: ${Number(c.coord_x).toFixed(2)} · Y: ${Number(c.coord_y).toFixed(2)} · Z: ${Number(c.coord_z).toFixed(2)}</small>`;if(window.dispatchMap)window.dispatchMap.panTo(gtaToMapPoint(c.coord_x,c.coord_y))}
async function changeCallStatus(id,action){try{await api(`/api/calls/${id}`,{method:"PATCH",body:JSON.stringify({action})});toast(action==="accept"?"Opkald overtaget":action==="release"?"Opkald frigivet":"Opkald afsluttet");await calls()}catch(e){toast(e.message,"error");await calls()}}
async function setCallGPS(id){const c=(window.callRows||[]).find(x=>Number(x.id)===Number(id));if(!c)return;const coords=`${Number(c.coord_x).toFixed(2)}, ${Number(c.coord_y).toFixed(2)}, ${Number(c.coord_z).toFixed(2)}`;try{await navigator.clipboard.writeText(coords);toast(`Koordinater kopieret: ${coords}`)}catch{prompt("Kopiér GPS-koordinaterne til din FiveM GPS",coords)}}
function callForm(){return `<form class="form"><div class="form-grid"><label>Navn<input name="caller_name" placeholder="Ukendt" maxlength="160"></label><label>Telefonnummer<input name="caller_phone" type="tel" maxlength="60"></label><label>Kategori<select name="category"><option>112</option><option>Færdselsuheld</option><option>Indbrud</option><option>Uro</option><option>Andet</option></select></label><label class="wide">Besked<textarea name="message" required maxlength="2000" placeholder="Hvad sker der?"></textarea></label><label>X-koordinat<input id="callX" name="x" type="number" step="0.01" value="0" required></label><label>Y-koordinat<input id="callY" name="y" type="number" step="0.01" value="0" required></label><label>Z-koordinat<input id="callZ" name="z" type="number" step="0.01" value="0"></label></div><div class="coordinate-picker"><div class="picker-hint">Klik på GTA V-kortet for at vælge opkaldets X/Y-koordinater.</div><div id="coordinatePicker" class="dispatch-map picker-map" role="application" aria-label="Vælg opkaldets placering på GTA V-kortet"></div></div><button class="btn primary-btn" type="submit">Opret opkald</button></form>`}
function newCall(){modal("Opret opkald",callForm(),async f=>{const payload=Object.fromEntries(f);payload.x=Number(payload.x);payload.y=Number(payload.y);payload.z=Number(payload.z||0);await api("/api/calls",{method:"POST",body:JSON.stringify(payload)})});setTimeout(()=>mountCallMap([],true),120)}
function chooseCallCoordinates(event,map){const {x,y}=mapPointToGta(event.latlng,map);$("#callX").value=x;$("#callY").value=y;if(window.coordinatePickMarker)window.coordinatePickMarker.setLatLng(gtaToMapPoint(x,y));toast(`Position valgt: ${x}, ${y}`)}

async function board(){const rows=await api("/api/board");window.boardRows=rows;const guides=rows.filter(p=>p.pinned).slice(0,3);const latest=[...rows].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))[0];
  const guideRows=guides.length?guides.map(p=>`<button class="guide-link" onclick="editPostById(${p.id})"><span>${esc(p.title)}</span><b>→</b></button>`).join(""):`<button class="guide-link" onclick="location.hash='fleet'"><span>Flådestyring</span><b>→</b></button><button class="guide-link" onclick="location.hash='calls'"><span>Opkaldsliste</span><b>→</b></button>`;
  const body=`<div class="board-reference-top"><section class="panel board-guides" id="board-guides"><div class="panel-head"><h2>Guides / Tutorials</h2><button class="icon-btn" title="Opret guide" onclick="newGuide()">＋</button></div>${guideRows}</section><section class="panel board-daily"><div class="panel-head"><h2>Dagens Besked</h2></div><div class="board-quote-mark">“</div><blockquote>${latest?esc(latest.body):"Hej med jer"}</blockquote><div class="board-quote-author"><span class="avatar avatar-sm">${esc(initials(latest?.author_name||"POLITI"))}</span><span>${esc(latest?.author_name||"Rigspolitiet")}<small>${esc(latest?.rank||"Rigspolitichef")}</small></span></div></section><section class="panel board-admin"><div class="panel-head"><h2>Administrer Opslagstavle</h2></div><div class="board-admin-actions"><button onclick="newPost()"><span>▣</span><span><b>Opret Opslag</b><small>Opret nyt opslag</small></span></button><button onclick="newGuide()"><span>▧</span><span><b>Opret en Guide</b><small>Opret ny guide</small></span></button><button onclick="document.getElementById('board-posts').scrollIntoView({behavior:'smooth'})"><span>✎</span><span><b>Ret Opslag</b><small>Rediger dine opslag</small></span></button><button onclick="document.getElementById('board-guides').scrollIntoView({behavior:'smooth'})"><span>◇</span><span><b>Ret Guides</b><small>Fastgjorte opslag</small></span></button></div></section></div>${rows.length?`<div class="board-grid" id="board-posts">${rows.map(p=>`<article class="post-card ${p.pinned?"pinned":""}"><div class="post-top"><span class="tag ${p.pinned?"tag-purple":""}">${p.pinned?"◆ Guide":"Opslag"}</span><span class="post-date">${date(p.created_at,true)}</span></div><h2>${esc(p.title)}</h2><p>${esc(p.body)}</p><div class="post-footer"><span class="avatar avatar-sm">${esc(initials(p.author_name))}</span><span><b>${esc(p.author_name||"Ukendt" )}</b><small>${esc(p.rank||"Politi")}</small></span><div class="post-actions">${fullAccess()||Number(p.author_id)===Number(me?.id)?`<button class="icon-btn" title="Rediger" onclick="editPostById(${p.id})">✎</button><button class="icon-btn danger-text" title="Slet" onclick="deletePost(${p.id})">×</button>`:""}</div></div></article>`).join("")}</div>`:empty("Opslagstavlen er tom","Opret et opslag, så alle kan se vigtige informationer.")}`;
  shell("Opslagstavle","Beskeder, driftsinformation og vejledninger til hele politiet.",body);
}
function postForm(p={}){return `<form class="form"><label>Overskrift<input name="title" value="${esc(p.title)}" required maxlength="180"></label><label>Besked<textarea name="body" required>${esc(p.body)}</textarea></label><label class="checkline"><input name="pinned" type="checkbox" ${p.pinned?"checked":""}> Fastgør øverst på opslagstavlen som guide</label><button class="btn primary-btn" type="submit">Gem opslag</button></form>`}
function newPost(pinned=false){modal(pinned?"Opret guide":"Nyt opslag",postForm({pinned}),async f=>{const o=Object.fromEntries(f);o.pinned=f.get("pinned")==="on";await api("/api/board",{method:"POST",body:JSON.stringify(o)})})}
function newGuide(){newPost(true)}
function editPost(p){modal("Rediger opslag",postForm(p),async f=>{const o=Object.fromEntries(f);o.pinned=f.get("pinned")==="on";await api(`/api/board/${p.id}`,{method:"PATCH",body:JSON.stringify(o)})})}
function editPostById(id){const p=window.boardRows.find(x=>x.id===id);if(p)editPost(p)}
async function deletePost(id){if(!confirm("Vil du slette dette opslag?"))return;await api(`/api/board/${id}`,{method:"DELETE"});toast("Opslaget er slettet");await board()}

async function fines(){const qv=new URLSearchParams(location.search).get("q")||"";const rows=await api("/api/fines?search="+encodeURIComponent(qv));const categories=[...new Set(rows.map(f=>f.category))];
  const extra=fullAccess()&&String(publicSettings.custom_fines_enabled??"true")!=="false"?`<button class="btn primary-btn" onclick="newFine()">＋ Ny bødetakst</button>`:"";
  const body=`<div class="toolbar"><form class="searchbar" onsubmit="searchFines(event)"><input class="search" id="searchInput" value="${esc(qv)}" placeholder="Søg efter titel, kode eller kategori"><button class="btn" type="submit">Søg</button></form>${extra}</div>${categories.length?`<div class="category-chips"><button class="chip active" onclick="filterFines('all',this)">Alle <span>${rows.length}</span></button>${categories.map((c,i)=>`<button class="chip" onclick="filterFinesByIndex(${i},this)">${esc(c)}</button>`).join("")}</div>`:""}<div id="fineTable">${fineTable(rows)}</div>`;
  shell("Bødetakster","Gældende takster fra straffe- og færdselslovgivningen.",body);window.fineRows=rows;window.fineCategories=categories;
}
function searchFines(e){e.preventDefault();location.search="?q="+encodeURIComponent($("#searchInput").value.trim())}
function fineTable(rows){const canEdit=fullAccess()&&String(publicSettings.custom_fines_enabled??"true")!=="false";return table(["LOV","PARAGRAF","SIGTELSE / INFORMATION","BØDE","KLIP","FÆNGSEL",...(canEdit?[""]:[])],rows.map(f=>`<tr><td><span class="category-label">${esc(f.category)}</span></td><td class="mono">${esc(f.code||"—")}</td><td><b>${esc(f.title)}</b><small class="cell-sub">${esc(f.description||"")}</small></td><td class="money">${money(f.price_dkk)}</td><td>${Number(f.points)||0}</td><td>${prisonTerm(f)}</td>${canEdit?`<td class="right"><button class="icon-btn" onclick="editFineById(${f.id})">✎</button><button class="icon-btn danger-text" onclick="deleteFine(${f.id})">×</button></td>`:""}</tr>`),"Ingen lovparagraffer fundet")}
function filterFines(category,button){document.querySelectorAll(".chip").forEach(x=>x.classList.remove("active"));button.classList.add("active");$("#fineTable").innerHTML=fineTable(category==="all"?window.fineRows:window.fineRows.filter(f=>f.category===category))}
function filterFinesByIndex(index,button){filterFines(window.fineCategories[index],button)}
function fineForm(f={}){return `<form class="form"><div class="form-grid"><label>Lov / kategori<input name="category" value="${esc(f.category)}" required></label><label>Paragraf<input name="code" value="${esc(f.code)}"></label><label class="wide">Sigtelse<input name="title" value="${esc(f.title)}" required></label><label>Bøde (DKK)<input type="number" name="price_dkk" min="0" value="${Number(f.price_dkk)||0}" required></label><label>Klip<input type="number" name="points" min="0" value="${Number(f.points)||0}"></label><label>Fængsel (dage)<input type="number" name="prison_days" min="0" value="${Number(f.prison_days)||0}"></label><label>Fængsel (måneder)<input type="number" name="prison_months" min="0" value="${Number(f.prison_months)||0}"></label><label class="wide">Information / beskrivelse<textarea name="description">${esc(f.description)}</textarea></label></div><button class="btn primary-btn" type="submit">Gem takst</button></form>`}
function newFine(){if(!fullAccess())return toast("Kun administratorer kan ændre bødetakster","error");if(String(publicSettings.custom_fines_enabled??"true")==="false")return toast("Egne bødetakster er slået fra i indstillingerne","error");modal("Ny bødetakst",fineForm(),async f=>api("/api/fines",{method:"POST",body:JSON.stringify(Object.fromEntries(f))}))}
function editFine(f){modal("Rediger bødetakst",fineForm(f),async x=>api(`/api/fines/${f.id}`,{method:"PATCH",body:JSON.stringify(Object.fromEntries(x))}))}
function editFineById(id){const f=window.fineRows.find(x=>x.id===id);if(f)editFine(f)}
async function deleteFine(id){if(!confirm("Vil du slette denne bødetakst?"))return;await api(`/api/fines/${id}`,{method:"DELETE"});toast("Bødetaksten er slettet");await fines()}

async function employees(){const rows=await api("/api/employees");window.employeeRows=rows;const manager=staffManager();window.rankRows=await api("/api/ranks");
  shell("Ansatte","Politiets medarbejdere og deres tjenesteoplysninger.",`${manager?`<div class="toolbar"><span>${fullAccess()?"Fuld administration":"Du kan administrere medarbejdere under dit eget niveau"}</span><button class="btn primary-btn" onclick="newEmployee()">＋ Opret ansat</button></div>`:""}${table(["MEDARBEJDER","RANG","SKILT","ROLLE","STATUS",...(manager?[""]:[])],rowsFrom(rows,e=>{const canEdit=fullAccess()||(manager&&e.role!=="admin"&&Number(e.rank_level)<Number(me.rank_level));const status=e.employment_status||(e.active?"Aktiv":"Inaktiv");const statusClass={Aktiv:"open",Inaktiv:"closed",Syg:"sick",Ferie:"vacation",Suspenderet:"suspended"}[status]||"closed";return `<tr><td><span class="person-cell"><span class="avatar">${esc(initials(e.full_name))}</span><span><b>${esc(e.full_name)}</b><small class="cell-sub">${esc(e.username)}</small></span></span></td><td>${esc(e.rank)}</td><td class="mono">${esc(e.badge_number||"—")}</td><td>${e.role==="admin"||Number(e.rank_level)>=10?"Administrator":"Betjent"}</td><td><div class="employee-status-cell"><div class="employee-status-copy"><span class="status ${statusClass}">${esc(status)}</span>${e.return_date?`<small>Tilbage ${date(e.return_date)}</small>`:""}</div>${canEdit?`<button class="calendar-icon-btn icon-btn" type="button" title="${e.return_date?`Returdato ${date(e.return_date)}`:"Sæt forventet returdato"}" aria-label="Sæt returdato for ${esc(e.full_name)}" onclick="editReturnDate(${e.id})">▦</button>`:""}</div></td>${manager?`<td class="right">${canEdit?`<button class="btn subtle" onclick="editEmployeeById(${e.id})">Rediger / fyr</button>`:"—"}</td>`:""}</tr>`}),"Der er ingen ansatte at vise")}`);
}
function editReturnDate(id){const employee=(window.employeeRows||[]).find(e=>Number(e.id)===Number(id));if(!employee)return;const current=String(employee.return_date||"").slice(0,10);modal(`Returdato · ${employee.full_name}`,`<form class="form"><label>Dato medarbejderen skal være tilbage<input type="date" name="return_date" value="${esc(current)}"></label><small class="muted">Lad datoen være tom for at fjerne returdatoen.</small><button class="btn primary-btn" type="submit">Gem returdato</button></form>`,async f=>{const value=f.get("return_date");await api(`/api/employees/${id}`,{method:"PATCH",body:JSON.stringify({return_date:value||null})})})}
function rankField(current=""){const rows=(window.rankRows||[]).filter(r=>fullAccess()||Number(r.level)<Number(me.rank_level)),selected=current||rows.find(r=>Number(r.level)===1)?.name||rows[0]?.name||"";return `<select name="rank" required>${rows.map(r=>`<option value="${esc(r.name)}" ${r.name===selected?"selected":""}>Rang ${Number(r.level)} · ${esc(r.name)}</option>`).join("")}${selected&&!rows.some(r=>r.name===selected)?`<option selected>${esc(selected)}</option>`:""}</select>`}
function employeeForm(e={},creating=false){const currentStatus=e.employment_status||(e.active?"Aktiv":"Inaktiv");const statuses=["Aktiv","Inaktiv","Syg","Ferie","Suspenderet"];return `<form class="form"><div class="form-grid">${creating?`<label>Brugernavn<input name="username" required></label><label>Adgangskode<input name="password" type="password" minlength="8" required></label>`:`<div class="readonly wide">Brugernavn <b>${esc(e.username)}</b></div>`}<label class="wide">Fulde navn<input name="full_name" value="${esc(e.full_name)}" required></label><label>Rang${rankField(e.rank||"")}</label><label>Skiltenummer<input name="badge_number" value="${esc(e.badge_number)}"></label>${fullAccess()?`<label>Rolle<select name="role"><option value="officer" ${e.role!=="admin"?"selected":""}>Betjent</option><option value="admin" ${e.role==="admin"?"selected":""}>Administrator</option></select></label>`:""}${creating?"":`<label>Status<select name="employment_status">${statuses.map(status=>`<option value="${status}" ${currentStatus===status?"selected":""}>${status}</option>`).join("")}</select></label>`}</div><button class="btn primary-btn" type="submit">Gem medarbejder</button>${creating?"":`<button class="btn danger" type="button" onclick="deleteEmployeeById(${e.id})">Fjern fra tabletten</button>`}</form>`}
function newEmployee(){modal("Opret ansat",employeeForm({},true),async f=>api("/api/employees",{method:"POST",body:JSON.stringify(Object.fromEntries(f))}))}
function editEmployee(e){modal("Rediger ansat",employeeForm(e),async f=>{const o=Object.fromEntries(f);await api(`/api/employees/${e.id}`,{method:"PATCH",body:JSON.stringify(o)})})}
function editEmployeeById(id){const e=window.employeeRows.find(x=>x.id===id);if(e)editEmployee(e)}
async function deleteEmployeeById(id){const e=(window.employeeRows||[]).find(x=>Number(x.id)===Number(id));if(!e)return;if(!confirm(`Fjern ${e.full_name} permanent fra tabletten? Historiske sager og logs bevares uden medarbejderkobling.`))return;try{await api(`/api/employees/${id}`,{method:"DELETE"});document.querySelector(".modal")?.remove();toast(`${e.full_name} er fjernet fra tabletten`);await employees()}catch(error){toast(error.message,"error")}}

async function ranks(){const rows=await api("/api/ranks");window.rankRows=rows;
  shell("Rangadministration","De 11 rangtrin følger den faste rangstige. Rang 10 og Admin har fuld adgang.",`<div class="toolbar"><span class="muted">${rows.length} rangtrin · rangniveauerne kan ikke ændres</span></div>${table(["RANG","NIVEAU","TILDELTE ANSATTE","HANDLINGER"],rowsFrom(rows,r=>`<tr><td><b>${esc(r.name)}</b></td><td>${Number(r.level)||0}</td><td>${Number(r.employee_count)||0}</td><td class="right"><button class="btn subtle" onclick="editRankById(${r.id})">Rediger navn</button></td></tr>`),"Der er endnu ingen rangtrin")}`);
}
function rankForm(r={}){return `<form class="form"><div class="readonly">Rang ${Number(r.level)} · Niveauet låses for at bevare rangstigen.</div><label>Rangnavn<input name="name" value="${esc(r.name)}" required maxlength="120"></label><p class="muted">Medarbejdere med denne rang følger automatisk med, hvis navnet ændres.</p><button class="btn primary-btn" type="submit">Gem navn</button></form>`}
function editRank(r){modal("Rediger rangnavn",rankForm(r),async f=>{const data=Object.fromEntries(f);await api(`/api/ranks/${r.id}`,{method:"PATCH",body:JSON.stringify(data)})})}
function editRankById(id){const r=(window.rankRows||[]).find(x=>Number(x.id)===Number(id));if(r)editRank(r)}
async function deleteRank(id,employeeCount){const rank=(window.rankRows||[]).find(r=>Number(r.id)===Number(id));if(!rank)return;if(employeeCount||Number(rank.employee_count))return toast("Tildel medarbejderne en anden rang, før du sletter denne","error");if(!confirm(`Vil du slette rangen ${rank.name}?`))return;try{await api(`/api/ranks/${id}`,{method:"DELETE"});toast(`Rangen ${rank.name} er slettet`);await ranks()}catch(e){toast(e.message,"error")}}

async function applications(){const rows=await api("/api/applications");window.applicationRows=rows;
  shell("Ansøgninger","Gennemgå nye ansøgninger, og registrer ansøgerens status.",`<div class="applications-layout"><section class="panel applications-main"><div class="panel-head"><h2>Ansøgningsmuligheder</h2></div><article class="application-option"><div><b>Civilpolitiet</b><small>Dette er en ansøgning til civilpolitiet.</small></div><button class="btn primary-btn" onclick="newApplication()">Ansøg</button></article><div class="panel-head applications-mine-head"><h2>Mine Ansøgninger <span class="count">${rows.length}</span></h2></div>${rows.length?`<div class="application-list">${rows.map(a=>`<article class="application-card"><div class="avatar">${esc(initials(a.applicant_name))}</div><div class="application-info"><div class="application-title"><h3>${esc(a.applicant_name)}</h3><span class="status ${a.status==="Afventer"?"waiting":a.status==="Godkendt"?"open":"closed"}">${esc(a.status)}</span></div><small>${esc(a.type)} · Indsendt ${date(a.created_at)}</small><p>${esc(a.message||"Ingen besked vedlagt.")}</p></div><div class="application-actions">${a.status==="Afventer"?`<button class="btn success" onclick="setApplication(${a.id},'Godkendt')">Besvar</button><button class="btn danger" onclick="setApplication(${a.id},'Afvist')">Afvis</button>`:`<button class="btn subtle" onclick="setApplication(${a.id},'Afventer')">Genåbn</button>`}</div></article>`).join("")}</div>`:empty("Ingen ansøgninger endnu","Indsendte ansøgninger vises her.")}</section><aside class="panel application-aside"><div class="panel-head"><h2>Administrer Ansøgninger</h2></div><div class="application-admin-actions"><button onclick="newApplication()"><span>▣</span><span><b>Opret Ansøgning</b><small>Opret ny ansøgning</small></span></button><button onclick="focusApplications('all')"><span>✎</span><span><b>Ret Ansøgninger</b><small>Se og administrer ansøgninger</small></span></button><button onclick="focusApplications('pending')"><span>↶</span><span><b>Besvar Ansøgninger</b><small>Gennemgå dem der afventer</small></span></button></div><div class="app-stat"><span class="stat-icon">◷</span><div><small>Afventer</small><b>${rows.filter(a=>a.status==="Afventer").length}</b></div></div><div class="app-stat"><span class="stat-icon green-icon">✓</span><div><small>Godkendt</small><b>${rows.filter(a=>a.status==="Godkendt").length}</b></div></div><div class="app-stat"><span class="stat-icon red-icon">×</span><div><small>Afvist</small><b>${rows.filter(a=>a.status==="Afvist").length}</b></div></div></aside></div>`);
}
function focusApplications(which){const list=document.querySelector(".application-list");if(which==="pending"){const pending=[...document.querySelectorAll(".application-card")].find(card=>card.querySelector(".status.waiting"));if(pending){pending.scrollIntoView({behavior:"smooth",block:"center"});pending.classList.add("application-focus");setTimeout(()=>pending.classList.remove("application-focus"),1600);return}}list?.scrollIntoView({behavior:"smooth",block:"start"});}
function newApplication(){modal("Opret ansøgning",`<form class="form"><label>Ansøgerens navn<input name="applicant_name" required></label><label>Ansøgningstype<select name="type"><option>Civilpolitiet</option><option>Betjent</option><option>Specialenhed</option><option>Andet</option></select></label><label>Besked<textarea name="message" placeholder="Skriv en kort ansøgning..."></textarea></label><button class="btn primary-btn" type="submit">Indsend ansøgning</button></form>`,async f=>api("/api/applications",{method:"POST",body:JSON.stringify(Object.fromEntries(f))}))}
async function setApplication(id,status){await api(`/api/applications/${id}`,{method:"PATCH",body:JSON.stringify({status})});toast("Ansøgning opdateret");await applications()}

async function logs(){const rows=await api("/api/logs");
  shell("Logs","Revisionsspor for handlinger foretaget i POLITI Tablet.",`<div class="toolbar"><div class="filter-tabs"><span class="selected static-tab">Seneste ${rows.length} hændelser</span></div><button class="btn subtle" onclick="logs()">↻ Opdater</button></div>${table(["HANDLING","TITEL","BESKRIVELSE","UDFØRT AF","DATO"],rowsFrom(rows,l=>`<tr><td><span class="log-action ${esc(l.action).toLowerCase()}">${esc(l.action)}</span></td><td><b>${esc(l.title)}</b></td><td class="log-desc">${esc(l.description||"—")}</td><td><span class="person-cell"><span class="avatar avatar-sm">${esc(initials(l.full_name))}</span>${esc(l.full_name||"System")}</span></td><td>${date(l.created_at,true)}</td></tr>`),"Ingen loghændelser")}`);
}

const settingGroups=[
  {title:"Generelt",items:[{key:"site_name",label:"Systemnavn",kind:"text",help:"Navnet der vises i POLITI Tablet."},{key:"language",label:"Sprog",kind:"select",options:["da","en"],help:"Vælg sproget i systemet."},{key:"frakendelse_years",label:"Frakendelse (år)",kind:"number",help:"Standardlængde for frakendelse."},{key:"license_points_limit",label:"Klip før frakendelse",kind:"number",help:"Antal klip før kørekortet frakendes."}]},
  {title:"Funktioner",items:[{key:"custom_fines_enabled",label:"Brug egne bødetakster",kind:"toggle",help:"Tillad at administrationen tilføjer egne takster."},{key:"applications_enabled",label:"Modtag ansøgninger",kind:"toggle",help:"Vis ansøgningsmodulet for medarbejdere."},{key:"warrants_enabled",label:"Efterlysninger",kind:"toggle",help:"Aktiver politiets efterlysningsregister."},{key:"board_enabled",label:"Opslagstavle",kind:"toggle",help:"Vis intern kommunikation på dashboardet."}]}
];
async function settings(){const preferences=await api("/api/preferences");const s=fullAccess()?await api("/api/settings"):{};
  const groups=settingGroups.map(g=>`<section class="settings-group"><div class="settings-group-title"><h2>${g.title}</h2><span>⚙</span></div>${g.items.map(i=>`<div class="setting-row"><div class="setting-copy"><b>${i.label}</b><small>${i.help}</small></div>${i.kind==="toggle"?`<label class="switch"><input type="checkbox" id="set_${i.key}" ${String(s[i.key]??"true")==="true"?"checked":""}><span></span></label>`:i.kind==="select"?`<select id="set_${i.key}">${i.options.map(o=>`<option value="${o}" ${(s[i.key]||"da")===o?"selected":""}>${o==="da"?"Dansk":"English"}</option>`).join("")}</select>`:`<input id="set_${i.key}" type="${i.kind}" value="${esc(s[i.key]??(i.key==="site_name"?"POLITI":"3"))}" ${i.kind==="number"?"min=0 max=100":""}>`}</div>`).join("")}</section>`).join("");
  const appearance=`<section class="settings-card appearance-settings"><div class="panel-head"><div><h2>Personligt udseende</h2><p class="muted">Disse valg gælder kun for din egen bruger.</p></div><span class="settings-shield">◐</span></div><div class="setting-row appearance-size"><div class="setting-copy"><b>Tekststørrelse</b><small>Tilpas størrelsen på tekst og brugerflade.</small></div><div class="size-control"><input id="appearanceFontScale" type="range" min="80" max="150" step="5" value="${Number(preferences.font_scale)||100}" oninput="previewAppearance()"><output id="appearanceFontScaleValue">${Number(preferences.font_scale)||100}%</output></div></div><div class="setting-row"><div class="setting-copy"><b>Tekstfarve</b><small>Vælg farven på den almindelige tekst.</small></div><input class="color-picker" id="appearanceTextColor" type="color" value="${esc(preferences.text_color||defaultAppearance.text_color)}" oninput="previewAppearance()"></div><div class="setting-row"><div class="setting-copy"><b>Tabletfarve</b><small>Vælg baggrundsfarven på din tablet.</small></div><input class="color-picker" id="appearanceTabletColor" type="color" value="${esc(preferences.tablet_color||defaultAppearance.tablet_color)}" oninput="previewAppearance()"></div><div class="settings-footer"><small>Ændringerne bliver gemt på din bruger.</small><div class="appearance-actions"><button class="btn subtle" onclick="resetAppearance()">Nulstil</button><button class="btn primary-btn" onclick="saveAppearance()">Gem udseende</button></div></div></section>`;
  const adminSettings=fullAccess()?`<section class="settings-layout"><div class="settings-card"><div class="panel-head"><div><h2>Systemindstillinger</h2><p class="muted">Gælder for alle brugere.</p></div></div>${groups}<div class="settings-footer"><small>Disse ændringer påvirker hele afdelingen.</small><button class="btn primary-btn" onclick="saveSettings()">Gem systemindstillinger</button></div></div><aside class="settings-aside"><div class="panel"><span class="settings-shield">⚙</span><h2>Systemadministration</h2><p class="muted">Administrer POLITI Tablets funktioner.</p><div class="connection"><span class="online-dot"></span><span>Forbindelse til databasen</span><b>Aktiv</b></div></div></aside></section>`:"";
  shell("Indstillinger","Tilpas din tablet eller administrer systemet.",`${appearance}${adminSettings}`);
}
function previewAppearance(){const scale=$("#appearanceFontScale");if(!scale)return;$("#appearanceFontScaleValue").value=`${scale.value}%`;$("#appearanceFontScaleValue").textContent=`${scale.value}%`;applyAppearance({font_scale:scale.value,text_color:$("#appearanceTextColor").value,tablet_color:$("#appearanceTabletColor").value})}
async function saveAppearance(){const prefs={font_scale:Number($("#appearanceFontScale").value),text_color:$("#appearanceTextColor").value,tablet_color:$("#appearanceTabletColor").value};applyAppearance(await api("/api/preferences",{method:"POST",body:JSON.stringify(prefs)}));toast("Dit udseende er gemt")}
async function resetAppearance(){const prefs=await api("/api/preferences",{method:"POST",body:JSON.stringify(defaultAppearance)});$("#appearanceFontScale").value=prefs.font_scale;$("#appearanceTextColor").value=prefs.text_color;$("#appearanceTabletColor").value=prefs.tablet_color;previewAppearance();toast("Udseendet er nulstillet")}
async function saveSettings(){const s={};for(const g of settingGroups)for(const i of g.items){const el=$("#set_"+i.key);s[i.key]=i.kind==="toggle"?String(el.checked):el.value}await api("/api/settings",{method:"POST",body:JSON.stringify(s)});applyPublicSettings({...publicSettings,...s});toast("Indstillinger gemt")}

async function cases(){const rows=await api("/api/cases");shell("Sager","Oprettede rapporter og sigtelser.",`${table(["SAGSNR.","PERSON","SAG / PARAGRAFFER","BETJENT","BØDE","KLIP","FÆNGSEL","DATO",...(canDeleteCases()?[""]:[])],rowsFrom(rows,c=>`<tr><td class="mono">${esc(c.case_number)}</td><td>${esc(c.person_name||"—")}</td><td>${esc(c.title)}${c.penalties?.length?`<small class="cell-sub">${esc(c.penalties.map(p=>`${p.code||p.title} × ${p.quantity}`).join(" · "))}</small>`:""}</td><td>${esc(c.officer_name||"—")}</td><td>${money(c.fine_dkk)}</td><td>${Number(c.license_points)||0}</td><td>${prisonTerm(c)}</td><td>${date(c.created_at)}</td>${canDeleteCases()?`<td class="right"><button class="icon-btn danger-text" aria-label="Slet sag ${esc(c.case_number)}" onclick="deleteCase(${c.id},'${esc(c.case_number)}')">×</button></td>`:""}</tr>`))}`)}
async function deleteCase(id,caseNumber){if(!confirm(`Vil du slette sag ${caseNumber} permanent?`))return;try{await api(`/api/cases/${id}`,{method:"DELETE"});toast(`Sag ${caseNumber} er slettet`);await cases()}catch(e){toast(e.message,"error")}}

const pages={dashboard,persons,vehicles,fleet,calls,warrants,board,fines,employees,ranks,applications,logs,settings,cases};
async function route(p){try{const feature={applications:"applications_enabled",warrants:"warrants_enabled",board:"board_enabled"}[p];if(feature&&String(publicSettings[feature]??"true")==="false"){toast("Denne funktion er slået fra i systemindstillingerne","error");p="dashboard"}await (pages[p]||dashboard)()}catch(e){content.innerHTML=`<div class="error-panel"><strong>Kunne ikke indlæse siden</strong><p>${esc(e.message)}</p><button class="btn" onclick="route('${esc(p)}')">Prøv igen</button></div>`}}
function updateUser(){if(!me)return;$("#userName").textContent=`${me.full_name} · ${me.rank}`;$("#profileInitials").textContent=initials(me.full_name);document.querySelectorAll(".adminOnly").forEach(x=>x.classList.toggle("hidden",!fullAccess()));}
function updateProfileImage(image=""){
  const preview=$("#profileImagePreview"),fallback=$("#profileImageFallback"),remove=$("#removeProfileImage");
  if(!preview||!fallback)return;
  const hasImage=Boolean(image);
  preview.src=hasImage?image:"";
  preview.classList.toggle("hidden",!hasImage);
  fallback.textContent=initials(me?.full_name);
  fallback.classList.toggle("hidden",hasImage);
  remove?.classList.toggle("hidden",!hasImage);
}
function applyPublicSettings(s={}){publicSettings=s;const name=s.site_name==="Dream Politi"||!s.site_name?"POLITI":s.site_name;document.title=`${name} Tablet`;document.querySelectorAll(".brand").forEach(el=>{el.textContent=name});document.querySelectorAll("[data-feature]").forEach(el=>el.classList.toggle("hidden",String(s[el.dataset.feature]??"true")==="false"));}
function applyAppearance(p={}){
  const value={...defaultAppearance,...p};
  const root=document.documentElement;
  root.style.setProperty("--font-scale",String(Math.min(150,Math.max(80,Number(value.font_scale)||100))/100));
  root.style.setProperty("--user-text-color",/^#[0-9a-f]{6}$/i.test(value.text_color)?value.text_color:defaultAppearance.text_color);
  root.style.setProperty("--text",/^#[0-9a-f]{6}$/i.test(value.text_color)?value.text_color:defaultAppearance.text_color);
  root.style.setProperty("--user-tablet-color",/^#[0-9a-f]{6}$/i.test(value.tablet_color)?value.tablet_color:defaultAppearance.tablet_color);
  root.style.setProperty("--bg","var(--user-tablet-color)");
  root.style.setProperty("--surface","color-mix(in srgb, var(--user-tablet-color) 91%, white)");
  root.style.setProperty("--surface-2","color-mix(in srgb, var(--user-tablet-color) 84%, white)");
  root.style.setProperty("--surface-3","color-mix(in srgb, var(--user-tablet-color) 77%, white)");
  updateProfileImage(value.profile_image||"");
}
async function showApp(){try{applyAppearance(await api("/api/preferences"))}catch{}updateUser();$("#login").classList.add("hidden");$("#app").classList.remove("hidden");route(location.hash.slice(1)||"dashboard")}
document.querySelectorAll("[data-page]").forEach(b=>b.onclick=()=>{const menu=b.closest(".profile-menu");if(menu)menu.open=false;history.replaceState(null,"",location.pathname+location.hash);location.hash=b.dataset.page});
window.addEventListener("hashchange",()=>route(location.hash.slice(1)||"dashboard"));
window.addEventListener("popstate",()=>route(location.hash.slice(1)||"dashboard"));
window.addEventListener("unhandledrejection",e=>{e.preventDefault();toast(e.reason?.message||"Handlingen kunne ikke gennemføres","error")});
$("#loginForm").onsubmit=async e=>{e.preventDefault();$("#loginError").textContent="";try{const r=await api("/api/login",{method:"POST",body:JSON.stringify({username:$("#username").value,password:$("#password").value})});me=r.user;showApp()}catch(x){$("#loginError").textContent=x.message}};
$("#logout").onclick=async()=>{try{await api("/api/logout",{method:"POST"})}finally{location.reload()}};
$("#profileImageInput").addEventListener("change",async e=>{
  const input=e.currentTarget,file=input.files?.[0];if(!file)return;
  if(!["image/png","image/jpeg","image/webp"].includes(file.type)){toast("Vælg et PNG-, JPG- eller WEBP-billede","error");input.value="";return}
  if(file.size>512*1024){toast("Billedet må højst være 512 KB","error");input.value="";return}
  const reader=new FileReader();
  reader.onerror=()=>{toast("Billedet kunne ikke læses","error");input.value=""};
  reader.onload=async()=>{try{const saved=await api("/api/profile-image",{method:"POST",body:JSON.stringify({image:reader.result})});updateProfileImage(saved.profile_image);toast("Profilbilledet er gemt")}catch(error){toast(error.message,"error")}finally{input.value=""}};
  reader.readAsDataURL(file);
});
$("#removeProfileImage").onclick=async()=>{try{await api("/api/profile-image",{method:"DELETE"});updateProfileImage("");toast("Profilbilledet er fjernet")}catch(error){toast(error.message,"error")}};
api("/api/public-settings").then(applyPublicSettings).catch(()=>{});
api("/api/me").then(r=>{me=r.user;showApp()}).catch(()=>{});

